CREATE TABLE "public"."servicos" (
  "id"        bigint        GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nome"      text          NOT NULL,
  "descricao" text,
  "preco"     numeric(10,2) NOT NULL,
  "duracao"   integer       NOT NULL,
  CONSTRAINT "ck_serv_duracao" CHECK (((duracao >= 5) AND (duracao <= 240))),
  CONSTRAINT "ck_serv_preco" CHECK ((preco > (0)::numeric)),
  CONSTRAINT "servicos_pkey" PRIMARY KEY (id),
  CONSTRAINT "uq_serv_nome" UNIQUE (nome)
);

ALTER TABLE "public"."servicos"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "catalogo_servicos_leitura" ON "public"."servicos"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

REVOKE ALL ON SEQUENCE "public"."servicos_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."servicos_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."servicos_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."servicos_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."servicos_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."servicos_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."servicos_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."servicos_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."servicos" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."servicos" TO "service_role";

REVOKE ALL ON TABLE "public"."servicos" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."servicos" TO "postgres";
